// 00_hello_dojo / ex1 - reference solution (author only, used by `dojo verify`).

export function greet(name: string): string {
  return `Hello, ${name}! Welcome to the dojo.`;
}

// 00_hello_dojo / ex2 - reference solution (author only, used by `dojo verify`).

export function describeTrack(name: string, lessons: number): string {
  const noun = lessons === 1 ? "lesson" : "lessons";
  return `${name}: ${lessons} ${noun}`;
}

// 00_hello_dojo / ex3 - reference solution (author only, used by `dojo verify`).

export function parseLessonNumber(slug: string): number {
  return Number.parseInt(slug.split("_")[0], 10);
}

