// 02_functions / challenge - reference solution (author only).

function fail(message: string): never {
  throw new Error(message);
}

export function retry(attempts: number, action: () => string): string {
  if (attempts < 1) {
    fail("retry: attempts must be at least 1");
  }
  let lastError: unknown;
  for (let i = 0; i < attempts; i++) {
    try {
      return action();
    } catch (error) {
      lastError = error;
    }
  }
  throw lastError;
}

// 02_functions / ex1 - reference solution (author only).

export function progressLine(done: number, total = 12): string {
  const percent = Math.round((done / total) * 100);
  return `${done}/${total} (${percent}%)`;
}

// 02_functions / ex2 - reference solution (author only).

export function bestOf(...scores: number[]): number {
  let best = 0;
  for (const score of scores) {
    if (score > best) {
      best = score;
    }
  }
  return best;
}

// 02_functions / ex3 - reference solution (author only).

export function forEachTrack(
  names: readonly string[],
  visit: (name: string, index: number) => void,
): void {
  for (let i = 0; i < names.length; i++) {
    visit(names[i], i);
  }
}

// 02_functions / ex4 - reference solution (author only).

export function duplicate(value: string): string;
export function duplicate(value: number): number;
export function duplicate(value: string | number): string | number {
  if (typeof value === "string") {
    return value + value;
  }
  return value * 2;
}

// 02_functions / review1 - reference solution (author only).

export function padCell(text: string, width = 8, filler = "."): string {
  if (text.length >= width) {
    return text;
  }
  return text + filler.repeat(width - text.length);
}

