// 03_objects_interfaces / challenge - reference solution (author only).

export interface Lesson {
  slug: string;
  exercises: number;
}

export interface Part {
  title: string;
  lessons: readonly Lesson[];
}

export interface PartSummary {
  title: string;
  lessonCount: number;
  exerciseCount: number;
}

export function summarise(parts: readonly Part[]): PartSummary[] {
  return parts.map((part) => ({
    title: part.title,
    lessonCount: part.lessons.length,
    exerciseCount: part.lessons.reduce((total, lesson) => total + lesson.exercises, 0),
  }));
}

// 03_objects_interfaces / ex1 - reference solution (author only).

export interface Lesson {
  slug: string;
  title: string;
  exercises: number;
  challenge?: boolean;
}

export function describeLesson(lesson: Lesson): string {
  const line = `${lesson.slug}: ${lesson.title} - ${lesson.exercises} exercises`;
  return lesson.challenge ? `${line} + challenge` : line;
}

// 03_objects_interfaces / ex2 - reference solution (author only).

export interface Draft {
  readonly id: string;
  readonly title: string;
  readonly tags: readonly string[];
}

export function renameDraft(draft: Draft, title: string): Draft {
  return { ...draft, title };
}

// 03_objects_interfaces / ex3 - reference solution (author only).

export interface Tally {
  [slug: string]: number;
}

export function countAttempts(slugs: readonly string[]): Tally {
  const tally: Tally = {};
  for (const slug of slugs) {
    tally[slug] = (tally[slug] ?? 0) + 1;
  }
  return tally;
}

// 03_objects_interfaces / ex4 - reference solution (author only).

export interface RunOptions {
  retries?: number;
  verbose?: boolean;
  label?: string;
}

export interface ResolvedOptions {
  retries: number;
  verbose: boolean;
  label: string;
}

export function resolveOptions(options: RunOptions): ResolvedOptions {
  return {
    retries: options.retries ?? 1,
    verbose: options.verbose ?? false,
    label: options.label ?? "run",
  };
}

// 03_objects_interfaces / review1 - reference solution (author only).

export interface Learner {
  name: string;
  streak: number;
  nickname?: string;
}

export function greetLearner(learner: Learner): string {
  const shown = learner.nickname ?? learner.name;
  if (learner.streak === 0) {
    return `${shown} - no streak yet`;
  }
  return `${shown} - ${learner.streak} day streak`;
}

