// 04_unions_narrowing / challenge - reference solution (author only).

export type Result = { ok: true; value: string } | { ok: false; error: string };

export interface Partitioned {
  values: string[];
  errors: string[];
}

export function unwrapOr(result: Result, fallback: string): string {
  return result.ok ? result.value : fallback;
}

export function partition(results: readonly Result[]): Partitioned {
  const partitioned: Partitioned = { values: [], errors: [] };
  for (const result of results) {
    if (result.ok) {
      partitioned.values.push(result.value);
    } else {
      partitioned.errors.push(result.error);
    }
  }
  return partitioned;
}

// 04_unions_narrowing / ex1 - reference solution (author only).

export function formatCell(value: string | number | boolean): string {
  if (typeof value === "string") {
    return value;
  }
  if (typeof value === "number") {
    return value.toFixed(1);
  }
  return value ? "yes" : "no";
}

// 04_unions_narrowing / ex2 - reference solution (author only).

export type DojoEvent =
  | { kind: "pass"; exercise: string; attempts: number }
  | { kind: "fail"; exercise: string; message: string }
  | { kind: "hint"; exercise: string; tier: number };

export function describeEvent(event: DojoEvent): string {
  switch (event.kind) {
    case "pass":
      return `${event.exercise} passed after ${event.attempts} attempts`;
    case "fail":
      return `${event.exercise} failed: ${event.message}`;
    case "hint":
      return `${event.exercise} revealed hint ${event.tier}`;
  }
}

// 04_unions_narrowing / ex3 - reference solution (author only).

export type Failure = Error | { code: number; detail: string } | { timeoutMs: number };

export function explainFailure(failure: Failure): string {
  if (failure instanceof Error) {
    return `caught: ${failure.message}`;
  }
  if ("code" in failure) {
    return `http ${failure.code}: ${failure.detail}`;
  }
  return `timed out after ${failure.timeoutMs}ms`;
}

// 04_unions_narrowing / ex4 - reference solution (author only).

export type Shape =
  | { kind: "circle"; radius: number }
  | { kind: "square"; side: number }
  | { kind: "rect"; width: number; height: number };

export function assertNever(value: never): never {
  throw new Error(`unhandled variant: ${JSON.stringify(value)}`);
}

export function area(shape: Shape): number {
  switch (shape.kind) {
    case "circle":
      return Math.PI * shape.radius * shape.radius;
    case "square":
      return shape.side * shape.side;
    case "rect":
      return shape.width * shape.height;
    default:
      return assertNever(shape);
  }
}

// 04_unions_narrowing / review1 - reference solution (author only).

export type Payment =
  | { method: "cash" }
  | { method: "card"; last4: string }
  | { method: "transfer"; iban: string };

export function describePayment(payment: Payment): string {
  switch (payment.method) {
    case "cash":
      return "cash";
    case "card":
      return `card ending ${payment.last4}`;
    case "transfer":
      return `transfer to ${payment.iban}`;
  }
}

