// 05_literals_enums / challenge - reference solution (author only).

export const HINT_TIERS = {
  nudge: 1,
  approach: 2,
  almost: 3,
} as const;

export type Tier = keyof typeof HINT_TIERS;

export function sortTiers(tiers: readonly Tier[]): Tier[] {
  return [...tiers].sort((a, b) => HINT_TIERS[a] - HINT_TIERS[b]);
}

// 05_literals_enums / ex1 - reference solution (author only).

export type Level = "beginner" | "intermediate" | "advanced";

export function nextLevel(level: Level): Level {
  switch (level) {
    case "beginner":
      return "intermediate";
    case "intermediate":
      return "advanced";
    case "advanced":
      return "advanced";
  }
}

