// 06_generics_1 / challenge - reference solution (author only).

export function uniqueBy<T>(items: readonly T[], key: (item: T) => string): T[] {
  const seen = new Set<string>();
  const result: T[] = [];
  for (const item of items) {
    const k = key(item);
    if (!seen.has(k)) {
      seen.add(k);
      result.push(item);
    }
  }
  return result;
}

// 06_generics_1 / ex1 - reference solution (author only).

export function first<T>(items: readonly T[]): T | undefined {
  return items.length === 0 ? undefined : items[0];
}

// 06_generics_1 / ex2 - reference solution (author only).

export function mapArray<T, U>(
  items: readonly T[],
  transform: (item: T, index: number) => U,
): U[] {
  const result: U[] = [];
  for (let i = 0; i < items.length; i++) {
    result.push(transform(items[i], i));
  }
  return result;
}

// 06_generics_1 / ex3 - reference solution (author only).

export interface Box<T> {
  readonly value: T;
  map<U>(transform: (value: T) => U): Box<U>;
}

export function box<T>(value: T): Box<T> {
  return {
    value,
    map<U>(transform: (value: T) => U): Box<U> {
      return box(transform(value));
    },
  };
}

// 06_generics_1 / ex4 - reference solution (author only).

export function zipPairs<A, B>(a: readonly A[], b: readonly B[]): [A, B][] {
  const pairs: [A, B][] = [];
  const length = Math.min(a.length, b.length);
  for (let i = 0; i < length; i++) {
    pairs.push([a[i], b[i]]);
  }
  return pairs;
}

// 06_generics_1 / review1 - reference solution (author only).

export function lastOr<T>(items: readonly T[], fallback: T): T {
  return items.length === 0 ? fallback : items[items.length - 1];
}

