// 07_generics_2 / challenge - reference solution (author only).

export function getIn<T, K1 extends keyof T, K2 extends keyof T[K1]>(
  source: T,
  first: K1,
  second: K2,
): T[K1][K2] {
  return source[first][second];
}

// 07_generics_2 / ex1 - reference solution (author only).

export function pluck<T, K extends keyof T>(items: readonly T[], key: K): T[K][] {
  return items.map((item) => item[key]);
}

// 07_generics_2 / ex2 - reference solution (author only).

export function longest<T extends { length: number }>(a: T, b: T): T {
  return b.length > a.length ? b : a;
}

// 07_generics_2 / ex3 - reference solution (author only).

export class Registry<T = string> {
  private readonly entries = new Map<string, T>();

  set(key: string, value: T): void {
    this.entries.set(key, value);
  }

  get(key: string): T | undefined {
    return this.entries.get(key);
  }

  has(key: string): boolean {
    return this.entries.has(key);
  }

  get size(): number {
    return this.entries.size;
  }
}

// 07_generics_2 / ex4 - reference solution (author only).

export function indexBy<T, K extends keyof T>(items: readonly T[], key: K): Map<T[K], T> {
  const index = new Map<T[K], T>();
  for (const item of items) {
    index.set(item[key], item);
  }
  return index;
}

// 07_generics_2 / review1 - reference solution (author only).

export function firstWith<T, K extends keyof T>(
  items: readonly T[],
  key: K,
  value: T[K],
): T | undefined {
  return items.find((item) => item[key] === value);
}

