// 08_utility_types / challenge - reference solution (author only).

export type MyOmit<T, K extends keyof T> = { [P in Exclude<keyof T, K>]: T[P] };

export function omitKeys<T extends object, K extends keyof T>(
  source: T,
  keys: readonly K[],
): MyOmit<T, K> {
  const copy: Record<string, unknown> = { ...source };
  for (const key of keys) {
    delete copy[key as string];
  }
  return copy as MyOmit<T, K>;
}

// 08_utility_types / ex1 - reference solution (author only).

export function applyPatch<T extends object>(base: T, patch: Partial<T>): T {
  const merged = { ...base };
  for (const [key, value] of Object.entries(patch)) {
    if (value !== undefined) {
      (merged as Record<string, unknown>)[key] = value;
    }
  }
  return merged;
}

// 08_utility_types / ex2 - reference solution (author only).

export interface User {
  id: string;
  email: string;
  passwordHash: string;
  createdAt: string;
}

export type PublicUser = Omit<User, "passwordHash">;

export type UserSummary = Pick<User, "id" | "email">;

export function toPublicUser(user: User): PublicUser {
  const { passwordHash, ...rest } = user;
  return rest;
}

export function toSummary(user: User): UserSummary {
  return { id: user.id, email: user.email };
}

// 08_utility_types / ex3 - reference solution (author only).

export type MyPartial<T> = { [K in keyof T]?: T[K] };

export type MyPick<T, K extends keyof T> = { [P in K]: T[P] };

export function pickKeys<T extends object, K extends keyof T>(
  source: T,
  keys: readonly K[],
): MyPick<T, K> {
  const picked = {} as MyPick<T, K>;
  for (const key of keys) {
    picked[key] = source[key];
  }
  return picked;
}

// 08_utility_types / ex4 - reference solution (author only).

export type Loader = () => Promise<{ id: string; title: string }>;

export type Loaded = Awaited<ReturnType<Loader>>;

export function once<F extends (...args: any[]) => any>(
  fn: F,
): (...args: Parameters<F>) => ReturnType<F> {
  let called = false;
  let result: ReturnType<F>;
  return (...args: Parameters<F>): ReturnType<F> => {
    if (!called) {
      called = true;
      result = fn(...args);
    }
    return result;
  };
}

// 08_utility_types / review1 - reference solution (author only).

export type Verdict = "pass" | "fail" | "skip";

export type ScoreBoard = Record<Verdict, number>;

export function tallyVerdicts(verdicts: readonly Verdict[]): ScoreBoard {
  const board: ScoreBoard = { pass: 0, fail: 0, skip: 0 };
  for (const verdict of verdicts) {
    board[verdict] += 1;
  }
  return board;
}

