// 09_mapped_conditional / challenge - reference solution (author only).

export type DeepReadonly<T> = {
  readonly [K in keyof T]: T[K] extends object ? DeepReadonly<T[K]> : T[K];
};

export function deepFreeze<T extends object>(value: T): DeepReadonly<T> {
  for (const nested of Object.values(value)) {
    if (typeof nested === "object" && nested !== null) {
      deepFreeze(nested as object);
    }
  }
  return Object.freeze(value) as DeepReadonly<T>;
}

// 09_mapped_conditional / ex1 - reference solution (author only).

export type Mutable<T> = { -readonly [K in keyof T]: T[K] };

export function thaw<T extends object>(frozen: T): Mutable<T> {
  return { ...frozen };
}

// 09_mapped_conditional / ex2 - reference solution (author only).

export type Getters<T> = {
  [K in keyof T & string as `get${Capitalize<K>}`]: () => T[K];
};

export function makeGetters<T extends object>(source: T): Getters<T> {
  const getters: Record<string, () => unknown> = {};
  for (const key of Object.keys(source)) {
    const name = `get${key.charAt(0).toUpperCase()}${key.slice(1)}`;
    getters[name] = () => source[key as keyof T];
  }
  return getters as Getters<T>;
}

// 09_mapped_conditional / ex3 - reference solution (author only).

export type ElementOf<T> = T extends readonly (infer U)[] ? U : T;

export function flattenOnce<T>(items: readonly T[]): ElementOf<T>[] {
  const flat: ElementOf<T>[] = [];
  for (const item of items) {
    if (Array.isArray(item)) {
      flat.push(...(item as ElementOf<T>[]));
    } else {
      flat.push(item as ElementOf<T>);
    }
  }
  return flat;
}

// 09_mapped_conditional / ex4 - reference solution (author only).

export type MyExclude<T, U> = T extends U ? never : T;

export type BoxEach<T> = T extends unknown ? T[] : never;

export type BoxAll<T> = [T] extends [unknown] ? T[] : never;

export function withoutValues<T extends string, U extends T>(
  values: readonly T[],
  remove: readonly U[],
): MyExclude<T, U>[] {
  const removed = new Set<string>(remove);
  return values.filter((value) => !removed.has(value)) as MyExclude<T, U>[];
}

