// 10_guards_assertions / challenge - reference solution (author only).

export interface Submission {
  slug: string;
  attempts: number;
  passed: boolean;
}

export type Validated<T> = { ok: true; value: T } | { ok: false; errors: string[] };

export function validateSubmission(input: unknown): Validated<Submission> {
  if (typeof input !== "object" || input === null) {
    return { ok: false, errors: ["expected an object"] };
  }
  const candidate = input as Record<string, unknown>;
  const errors: string[] = [];
  if (typeof candidate.slug !== "string") {
    errors.push("slug must be a string");
  }
  if (typeof candidate.attempts !== "number") {
    errors.push("attempts must be a number");
  }
  if (typeof candidate.passed !== "boolean") {
    errors.push("passed must be a boolean");
  }
  if (errors.length > 0) {
    return { ok: false, errors };
  }
  return {
    ok: true,
    value: {
      slug: candidate.slug as string,
      attempts: candidate.attempts as number,
      passed: candidate.passed as boolean,
    },
  };
}

// 10_guards_assertions / ex1 - reference solution (author only).

export interface Lesson {
  slug: string;
  exercises: number;
}

export function isLesson(value: unknown): value is Lesson {
  if (typeof value !== "object" || value === null) {
    return false;
  }
  const candidate = value as Record<string, unknown>;
  return typeof candidate.slug === "string" && typeof candidate.exercises === "number";
}

// 10_guards_assertions / ex2 - reference solution (author only).

export function assertIsStringArray(value: unknown): asserts value is string[] {
  if (!Array.isArray(value) || value.some((item) => typeof item !== "string")) {
    throw new Error("expected an array of strings");
  }
}

// 10_guards_assertions / ex3 - reference solution (author only).

export function parseJson(text: string): unknown {
  return JSON.parse(text);
}

export function readTitle(value: unknown): string | null {
  if (typeof value !== "object" || value === null) {
    return null;
  }
  const title = (value as Record<string, unknown>).title;
  return typeof title === "string" ? title : null;
}

// 10_guards_assertions / ex4 - reference solution (author only).

export type Setting = string | number | boolean;

export const settings = {
  label: "nightly",
  retries: 3,
  verbose: true,
} satisfies Record<string, Setting>;

export function describeSettings(): string {
  const suffix = settings.verbose ? " (verbose)" : "";
  return `${settings.label.toUpperCase()} x${settings.retries}${suffix}`;
}

