// 11_async_and_modules / challenge - reference solution (author only).

export type TaskResult<T> = { ok: true; value: T } | { ok: false; error: string };

function messageOf(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

export async function runTasks<T>(
  tasks: readonly (() => Promise<T>)[],
  limit: number,
): Promise<TaskResult<T>[]> {
  if (!Number.isInteger(limit) || limit < 1) {
    throw new Error("runTasks: limit must be at least 1");
  }
  const results: TaskResult<T>[] = new Array(tasks.length);
  let next = 0;

  async function worker(): Promise<void> {
    while (next < tasks.length) {
      const index = next;
      next += 1;
      try {
        results[index] = { ok: true, value: await tasks[index]() };
      } catch (error) {
        results[index] = { ok: false, error: messageOf(error) };
      }
    }
  }

  const workers: Promise<void>[] = [];
  for (let i = 0; i < Math.min(limit, tasks.length); i++) {
    workers.push(worker());
  }
  await Promise.all(workers);
  return results;
}

// 11_async_and_modules / ex1 - reference solution (author only).

export interface Lesson {
  slug: string;
  title: string;
}

const LESSONS: Record<string, Lesson> = {
  "01_primitives_and_inference": { slug: "01_primitives_and_inference", title: "Primitives" },
  "04_unions_narrowing": { slug: "04_unions_narrowing", title: "Unions" },
};

export async function loadLesson(slug: string): Promise<Lesson> {
  const lesson = LESSONS[slug];
  if (lesson === undefined) {
    throw new Error(`unknown lesson: ${slug}`);
  }
  return lesson;
}

// 11_async_and_modules / ex2 - reference solution (author only).

export async function bothOf<A, B>(a: () => Promise<A>, b: () => Promise<B>): Promise<[A, B]> {
  return Promise.all([a(), b()]);
}

// 11_async_and_modules / ex3 - reference solution (author only).

export async function* pages(items: readonly string[], size: number): AsyncGenerator<string[]> {
  if (size < 1) {
    return;
  }
  for (let i = 0; i < items.length; i += size) {
    yield items.slice(i, i + size);
  }
}

export async function collect<T>(source: AsyncIterable<T>): Promise<T[]> {
  const all: T[] = [];
  for await (const item of source) {
    all.push(item);
  }
  return all;
}

