// d01_annotations_inference / ex1 - reference solution (author only).

export function formatReading(station: string, celsius: number): string {
  return `${station} ${celsius.toFixed(1)}C`;
}

// d01_annotations_inference / ex2 - reference solution (author only).

export function clockLabel(seconds: number): string {
  const total = Math.max(0, Math.floor(seconds));
  const minutes = Math.floor(total / 60);
  const rest = total % 60;
  return `${String(minutes).padStart(2, "0")}:${String(rest).padStart(2, "0")}`;
}

// d01_annotations_inference / ex3 - reference solution (author only).

export function splitStationId(id: string): [site: string, index: number] {
  const dash = id.lastIndexOf("-");
  if (dash === -1) {
    return [id, 0];
  }
  const tail = id.slice(dash + 1);
  if (tail === "" || !/^\d+$/.test(tail)) {
    return [id, 0];
  }
  return [id.slice(0, dash), Number(tail)];
}

// d01_annotations_inference / ex4 - reference solution (author only).

export function topReadings(values: readonly number[], count: number): readonly number[] {
  if (count <= 0) {
    return [];
  }
  return [...values].sort((a, b) => b - a).slice(0, count);
}

// d01_annotations_inference / ex5 - reference solution (author only).

export function summarise(
  values: readonly number[],
): { count: number; mean: number; spread: number } {
  if (values.length === 0) {
    return { count: 0, mean: 0, spread: 0 };
  }
  let min = values[0];
  let max = values[0];
  let sum = 0;
  for (const value of values) {
    if (value < min) {
      min = value;
    }
    if (value > max) {
      max = value;
    }
    sum += value;
  }
  return { count: values.length, mean: sum / values.length, spread: max - min };
}

// d01_annotations_inference / ex6 - reference solution (author only).

export function parseCsvRow(row: string): [station: string, celsius: number, ok: boolean] {
  const fields = row.split(",").map((field) => field.trim());
  const raw = fields[1] ?? "";
  const celsius = raw !== "" && Number.isFinite(Number(raw)) ? Number(raw) : 0;
  return [fields[0] ?? "", celsius, fields[2] === "true"];
}

// d01_annotations_inference / ex7 - reference solution (author only).

export function movingAverage(values: readonly number[], window: number): number[] {
  if (!Number.isInteger(window) || window <= 0 || window > values.length) {
    return [];
  }
  const averages: number[] = [];
  let sum = 0;
  for (let i = 0; i < values.length; i += 1) {
    sum += values[i];
    if (i >= window) {
      sum -= values[i - window];
    }
    if (i >= window - 1) {
      averages.push(sum / window);
    }
  }
  return averages;
}

// d01_annotations_inference / ex8 - reference solution (author only).

export function runLengths(values: readonly number[]): [value: number, count: number][] {
  const runs: [value: number, count: number][] = [];
  for (const value of values) {
    const last = runs[runs.length - 1];
    if (last !== undefined && last[0] === value) {
      last[1] += 1;
    } else {
      runs.push([value, 1]);
    }
  }
  return runs;
}

