    expectTypeOf(joinPath()).toEqualTypeOf<string>();
    expectTypeOf(joinPath("a", "b", "c")).toEqualTypeOf<string>();
    // @ts-expect-error - every segment is a string.
    joinPath("a", 1);
  });

