// d02_functions_signatures / ex1 - reference solution (author only).

export function shelfLabel(title: string, author?: string): string {
  const trimmed = (author ?? "").trim();
  return trimmed === "" ? title : `${title} - ${trimmed}`;
}

// d02_functions_signatures / ex2 - reference solution (author only).

export function joinPath(...segments: string[]): string {
  const cleaned: string[] = [];
  for (const segment of segments) {
    const trimmed = segment.replace(/^\/+/, "").replace(/\/+$/, "");
    if (trimmed !== "") {
      cleaned.push(trimmed);
    }
  }
  return cleaned.join("/");
}

// d02_functions_signatures / ex3 - reference solution (author only).

export function countMatching(
  values: readonly string[],
  keep: (value: string) => boolean,
): number {
  let matched = 0;
  for (const value of values) {
    if (keep(value)) {
      matched += 1;
    }
  }
  return matched;
}

// d02_functions_signatures / ex4 - reference solution (author only).

export type Formatter = (value: number) => string;

export function formatAll(
  values: readonly number[],
  format: Formatter = (value) => value.toFixed(2),
): string[] {
  return values.map((value) => format(value));
}

// d02_functions_signatures / ex5 - reference solution (author only).

export function normaliseTag(tag: string): string;
export function normaliseTag(tags: string[]): string[];
export function normaliseTag(input: string | string[]): string | string[] {
  if (Array.isArray(input)) {
    return input.map((tag) => normaliseTag(tag));
  }
  return input.trim().toLowerCase().replace(/\s+/g, "-");
}

// d02_functions_signatures / ex6 - reference solution (author only).

export interface Counter {
  next(): number;
  peek(): number;
  reset(): void;
}

export function makeCounter(start: number = 0): Counter {
  let current = start;
  return {
    next(): number {
      const value = current;
      current += 1;
      return value;
    },
    peek(): number {
      return current;
    },
    reset(): void {
      current = start;
    },
  };
}

// d02_functions_signatures / ex7 - reference solution (author only).

export function buildQuery(
  base: string,
  params?: Record<string, string | number | boolean>,
): string {
  const entries = Object.entries(params ?? {}).sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));
  if (entries.length === 0) {
    return base;
  }
  const query = entries
    .map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(String(value))}`)
    .join("&");
  return `${base}?${query}`;
}

// d02_functions_signatures / ex8 - reference solution (author only).

export type Middleware = (input: string, next: (value: string) => string) => string;

export function runMiddleware(input: string, middleware: readonly Middleware[]): string {
  const dispatch = (index: number): ((value: string) => string) => {
    return (value: string): string => {
      const handler = middleware[index];
      if (handler === undefined) {
        return value;
      }
      return handler(value, dispatch(index + 1));
    };
  };
  return dispatch(0)(input);
}

