// d03_objects_shapes / ex1 - reference solution (author only).

export interface Track {
  title: string;
  artist: string;
  seconds: number;
  explicit?: boolean;
}

export function trackLine(track: Track): string {
  const suffix = track.explicit === true ? " [E]" : "";
  return `${track.title} - ${track.artist} (${track.seconds}s)${suffix}`;
}

// d03_objects_shapes / ex2 - reference solution (author only).

export interface AlbumInput {
  title: string;
  year?: number;
  label?: string;
}

export function describeAlbum(input: AlbumInput): string {
  const { title, label = "independent", year } = input;
  const yearText = year === undefined ? "unknown" : String(year);
  return `${title} [${label}] ${yearText}`;
}

// d03_objects_shapes / ex3 - reference solution (author only).

export interface Playlist {
  readonly id: string;
  name: string;
  readonly tracks: readonly string[];
}

export function addTrack(playlist: Playlist, title: string): Playlist {
  return { ...playlist, tracks: [...playlist.tracks, title] };
}

// d03_objects_shapes / ex4 - reference solution (author only).

export interface Contact {
  email?: string;
}

export interface Owner {
  name?: string;
  contact?: Contact;
}

export interface OwnedPlaylist {
  name: string;
  owner?: Owner;
}

export function contactLine(playlist: OwnedPlaylist): string {
  const name = playlist.owner?.name?.trim();
  const email = playlist.owner?.contact?.email?.trim();
  return `${name ? name : "anonymous"} <${email ? email : "no email"}>`;
}

// d03_objects_shapes / ex5 - reference solution (author only).

export interface PlayedTrack {
  artist: string;
  seconds: number;
}

export interface ArtistTotals {
  [artist: string]: { count: number; seconds: number };
}

export function byArtist(tracks: readonly PlayedTrack[]): ArtistTotals {
  const totals: ArtistTotals = {};
  for (const track of tracks) {
    const entry = (totals[track.artist] ??= { count: 0, seconds: 0 });
    entry.count += 1;
    entry.seconds += track.seconds;
  }
  return totals;
}

// d03_objects_shapes / ex6 - reference solution (author only).

export interface TrackMeta {
  genre?: string;
  mood?: string;
  era?: string;
}

export function presentTags(meta: TrackMeta): Record<string, string> {
  const present: Record<string, string> = {};
  for (const [key, value] of Object.entries(meta)) {
    if (typeof value === "string" && value.trim() !== "") {
      present[key] = value.trim();
    }
  }
  return present;
}

// d03_objects_shapes / ex7 - reference solution (author only).

export interface MetaTree {
  [key: string]: string | MetaTree;
}

export function flattenMeta(tree: MetaTree): Record<string, string> {
  const flat: Record<string, string> = {};
  const walk = (node: MetaTree, prefix: string): void => {
    for (const [key, value] of Object.entries(node)) {
      const path = prefix === "" ? key : `${prefix}.${key}`;
      if (typeof value === "string") {
        flat[path] = value;
      } else {
        walk(value, path);
      }
    }
  };
  walk(tree, "");
  return flat;
}

// d03_objects_shapes / ex8 - reference solution (author only).

export interface MetaRecord {
  [key: string]: string | number;
}

export function diffMeta(
  before: MetaRecord,
  after: MetaRecord,
): { added: string[]; removed: string[]; changed: string[] } {
  const added: string[] = [];
  const removed: string[] = [];
  const changed: string[] = [];
  for (const key of Object.keys(after)) {
    if (!(key in before)) {
      added.push(key);
    } else if (before[key] !== after[key]) {
      changed.push(key);
    }
  }
  for (const key of Object.keys(before)) {
    if (!(key in after)) {
      removed.push(key);
    }
  }
  return { added: added.sort(), removed: removed.sort(), changed: changed.sort() };
}

