// d04_interfaces_aliases / ex3 - reference solution (author only).

export interface Scorer {
  (white: number, black: number): string;
  label: string;
  total: number;
}

export function makeScorer(label: string): Scorer {
  const scorer: Scorer = Object.assign(
    (white: number, black: number): string => {
      scorer.total += 1;
      return `${white}-${black}`;
    },
    { label, total: 0 },
  );
  return scorer;
}

// d04_interfaces_aliases / ex4 - reference solution (author only).

export interface OpeningStats {
  total: number;
  [opening: string]: number;
}

export function topOpening(stats: OpeningStats): string {
  let best = "";
  let bestCount = -1;
  for (const [opening, count] of Object.entries(stats)) {
    if (opening === "total") {
      continue;
    }
    if (count > bestCount || (count === bestCount && opening < best)) {
      best = opening;
      bestCount = count;
    }
  }
  return best;
}

