// d04_interfaces_aliases / ex6 - reference solution (author only).

export interface Ledger {
  record(white: string, black: string, points: number): void;
  pointsFor(player: string): number;
  standings(): { player: string; points: number }[];
}

export class ArrayLedger implements Ledger {
  private readonly points = new Map<string, number>();

  private add(player: string, amount: number): void {
    this.points.set(player, (this.points.get(player) ?? 0) + amount);
  }

  record(white: string, black: string, points: number): void {
    this.add(white, points);
    this.add(black, 1 - points);
  }

  pointsFor(player: string): number {
    return this.points.get(player) ?? 0;
  }

  standings(): { player: string; points: number }[] {
    return [...this.points.entries()]
      .map(([player, points]) => ({ player, points }))
      .sort((a, b) => (b.points - a.points) || (a.player < b.player ? -1 : a.player > b.player ? 1 : 0));
  }
}

// d04_interfaces_aliases / ex7 - reference solution (author only).

export interface Clock {
  readonly startedAt: number;
  tick(): number;
}

export class StepClock implements Clock {
  readonly startedAt: number;
  private current: number;

  constructor(startedAt: number) {
    this.startedAt = startedAt;
    this.current = startedAt;
  }

  tick(): number {
    this.current += 1;
    return this.current;
  }
}

export interface ClockConstructor {
  new (startedAt: number): Clock;
}

export function runClock(ctor: ClockConstructor, startedAt: number, ticks: number): number {
  const clock = new ctor(startedAt);
  let last = startedAt;
  for (let i = 0; i < ticks; i += 1) {
    last = clock.tick();
  }
  return last;
}

// d04_interfaces_aliases / ex8 - reference solution (author only).

export interface Match {
  readonly white: string;
  readonly black: string;
  readonly winner?: string;
}

export interface Round {
  readonly name: string;
  readonly matches: readonly Match[];
}

export function nextRound(round: Round, name: string): Round {
  const winners: string[] = [];
  for (const match of round.matches) {
    if (match.winner !== undefined) {
      winners.push(match.winner);
    }
  }
  const matches: Match[] = [];
  for (let i = 0; i < winners.length; i += 2) {
    const white = winners[i];
    const black = winners[i + 1];
    if (black === undefined) {
      matches.push({ white, black: "", winner: white });
    } else {
      matches.push({ white, black });
    }
  }
  return { name, matches };
}

