// d05_unions_basics / ex1 - reference solution (author only).

export function cellWidth(value: string | number): number {
  if (typeof value === "string") {
    return value.trim().length;
  }
  return String(Math.abs(value)).replace(".", "").length;
}

// d05_unions_basics / ex2 - reference solution (author only).

export function toCellText(value: string | number | null): string {
  if (value === null) {
    return "-";
  }
  if (typeof value === "number") {
    return String(value);
  }
  const trimmed = value.trim();
  return trimmed === "" ? "-" : trimmed;
}

// d05_unions_basics / ex3 - reference solution (author only).

export function sumNumeric(values: readonly (string | number)[]): number {
  let total = 0;
  for (const value of values) {
    if (typeof value === "number") {
      total += value;
    }
  }
  return total;
}

// d05_unions_basics / ex4 - reference solution (author only).

export function splitCells(values: readonly (string | number)[]): {
  texts: string[];
  numbers: number[];
} {
  const texts: string[] = [];
  const numbers: number[] = [];
  for (const value of values) {
    if (typeof value === "string") {
      texts.push(value);
    } else {
      numbers.push(value);
    }
  }
  return { texts, numbers };
}

// d05_unions_basics / ex5 - reference solution (author only).

export type Id = string | number;

export function idKey(id: Id): string {
  return typeof id === "number" ? `n:${id}` : `s:${id}`;
}

export function sameId(a: Id, b: Id): boolean {
  return idKey(a) === idKey(b);
}

// d05_unions_basics / ex6 - reference solution (author only).

export function compact(values: readonly (string | null | undefined)[]): string[] {
  const kept: string[] = [];
  for (const value of values) {
    if (value !== null && value !== undefined) {
      kept.push(value);
    }
  }
  return kept;
}

// d05_unions_basics / ex7 - reference solution (author only).

export type Cell = string | number | boolean | null;

export function parseCells(row: string): Cell[] {
  return row.split(",").map((field) => {
    const text = field.trim();
    if (text === "") {
      return null;
    }
    if (text === "true") {
      return true;
    }
    if (text === "false") {
      return false;
    }
    const asNumber = Number(text);
    return Number.isFinite(asNumber) ? asNumber : text;
  });
}

// d05_unions_basics / ex8 - reference solution (author only).

export type Cell = string | number | boolean | null;

export type ColumnKind = "empty" | "string" | "number" | "boolean" | "mixed";

export function columnKinds(rows: readonly (readonly Cell[])[]): ColumnKind[] {
  let width = 0;
  for (const row of rows) {
    if (row.length > width) {
      width = row.length;
    }
  }

  const kinds: ColumnKind[] = [];
  for (let column = 0; column < width; column += 1) {
    let kind: ColumnKind = "empty";
    for (const row of rows) {
      const cell = column < row.length ? row[column] : null;
      if (cell === null) {
        continue;
      }
      const seen: ColumnKind =
        typeof cell === "string" ? "string" : typeof cell === "number" ? "number" : "boolean";
      if (kind === "empty") {
        kind = seen;
      } else if (kind !== seen) {
        kind = "mixed";
      }
    }
    kinds.push(kind);
  }
  return kinds;
}

