// d06_narrowing_guards / ex1 - reference solution (author only).

export function isNonEmptyString(value: unknown): value is string {
  return typeof value === "string" && value.trim() !== "";
}

// d06_narrowing_guards / ex2 - reference solution (author only).

export type ValueKind =
  | "string"
  | "number"
  | "boolean"
  | "undefined"
  | "null"
  | "array"
  | "object"
  | "function";

export function kindOf(value: unknown): ValueKind {
  if (value === null) {
    return "null";
  }
  if (Array.isArray(value)) {
    return "array";
  }
  const kind = typeof value;
  if (kind === "bigint" || kind === "symbol") {
    return "object";
  }
  return kind;
}

// d06_narrowing_guards / ex3 - reference solution (author only).

export interface Point {
  x: number;
  y: number;
}

export function isPoint(value: unknown): value is Point {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    return false;
  }
  const candidate = value as { x?: unknown; y?: unknown };
  return typeof candidate.x === "number" && typeof candidate.y === "number";
}

// d06_narrowing_guards / ex4 - reference solution (author only).

export function assertIsRecord(value: unknown): asserts value is Record<string, unknown> {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    throw new Error("expected a plain object");
  }
}

// d06_narrowing_guards / ex5 - reference solution (author only).

export function toMillis(value: number | string | Date): number {
  if (value instanceof Date) {
    return value.getTime();
  }
  if (typeof value === "number") {
    return value;
  }
  const trimmed = value.trim();
  if (/^-?\d+$/.test(trimmed)) {
    return Number(trimmed);
  }
  const parsed = Date.parse(trimmed);
  if (Number.isNaN(parsed)) {
    throw new Error(`cannot read a timestamp from ${value}`);
  }
  return parsed;
}

// d06_narrowing_guards / ex6 - reference solution (author only).

export interface Tag {
  name: string;
  weight: number;
}

export function isTag(value: unknown): value is Tag {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    return false;
  }
  const candidate = value as { name?: unknown; weight?: unknown };
  return typeof candidate.name === "string" && typeof candidate.weight === "number";
}

export function collectTags(values: readonly unknown[]): Tag[] {
  return values.filter(isTag);
}

// d06_narrowing_guards / ex7 - reference solution (author only).

export interface Config {
  host: string;
  port: number;
  tls: boolean;
}

export function readConfig(raw: unknown): Config {
  if (typeof raw !== "object" || raw === null || Array.isArray(raw)) {
    throw new Error("config: expected an object");
  }
  const record = raw as Record<string, unknown>;

  const host = record.host;
  if (typeof host !== "string" || host.trim() === "") {
    throw new Error("config: host must be a non-empty string");
  }

  const port = record.port;
  if (typeof port !== "number" || !Number.isInteger(port) || port < 1) {
    throw new Error("config: port must be a positive integer");
  }

  const tls = record.tls;
  if (typeof tls !== "boolean") {
    throw new Error("config: tls must be a boolean");
  }

  return { host: host.trim(), port, tls };
}

// d06_narrowing_guards / ex8 - reference solution (author only).

export type TextNode = string | number | readonly TextNode[];

export function flattenText(node: TextNode): string {
  if (typeof node === "string") {
    return node.trim();
  }
  if (typeof node === "number") {
    return String(node);
  }
  const parts: string[] = [];
  for (const child of node) {
    const text = flattenText(child);
    if (text !== "") {
      parts.push(text);
    }
  }
  return parts.join(" ");
}

