// d07_discriminated_unions / ex1 - reference solution (author only).

export type Cmd =
  | { kind: "insert"; cents: number }
  | { kind: "select"; slot: string }
  | { kind: "refund" };

export function describeCommand(cmd: Cmd): string {
  switch (cmd.kind) {
    case "insert":
      return `insert ${cmd.cents}c`;
    case "select":
      return `select ${cmd.slot}`;
    case "refund":
      return "refund";
  }
}

// d07_discriminated_unions / ex2 - reference solution (author only).

export interface MachineState {
  credit: number;
  dispensed: readonly string[];
  message: string;
}

export type Action =
  | { type: "coin"; cents: number }
  | { type: "buy"; slot: string; price: number }
  | { type: "refund" };

export function reduce(state: MachineState, action: Action): MachineState {
  switch (action.type) {
    case "coin": {
      const credit = state.credit + action.cents;
      return { ...state, credit, message: `credit ${credit}c` };
    }
    case "buy": {
      if (state.credit < action.price) {
        return { ...state, message: `need ${action.price - state.credit}c more` };
      }
      return {
        credit: state.credit - action.price,
        dispensed: [...state.dispensed, action.slot],
        message: `dispensed ${action.slot}`,
      };
    }
    case "refund":
      return { ...state, credit: 0, message: `refunded ${state.credit}c` };
  }
}

// d07_discriminated_unions / ex3 - reference solution (author only).

export type Load =
  | { status: "idle" }
  | { status: "loading"; startedAt: number }
  | { status: "done"; body: string }
  | { status: "failed"; error: string; retriable: boolean };

export function renderLoad(load: Load): string {
  switch (load.status) {
    case "idle":
      return "idle";
    case "loading":
      return `loading since ${load.startedAt}`;
    case "done":
      return `done: ${load.body}`;
    case "failed":
      return `failed: ${load.error} (${load.retriable ? "retry" : "give up"})`;
  }
}

// d07_discriminated_unions / ex4 - reference solution (author only).

export type Frame =
  | { version: 1; payload: string }
  | { version: 2; payload: readonly string[]; codec: "gzip" | "raw" };

export function readFrame(frame: Frame): string {
  if (frame.version === 1) {
    return frame.payload;
  }
  const joined = frame.payload.join("|");
  return frame.codec === "gzip" ? `gzip(${joined})` : joined;
}

// d07_discriminated_unions / ex5 - reference solution (author only).

export type UiEvent =
  | { type: "click"; button: 0 | 1 | 2 }
  | { type: "key"; key: string; repeat: boolean }
  | { type: "scroll"; dy: number };

const BUTTON_NAMES = ["left", "middle", "right"] as const;

export function route(events: readonly UiEvent[]): string[] {
  return events.map((event) => {
    switch (event.type) {
      case "click":
        return `click:${BUTTON_NAMES[event.button]}`;
      case "key":
        return event.repeat ? `key:${event.key}(repeat)` : `key:${event.key}`;
      case "scroll":
        if (event.dy === 0) {
          return "scroll:none";
        }
        return event.dy < 0 ? `scroll:up:${-event.dy}` : `scroll:down:${event.dy}`;
    }
  });
}

// d07_discriminated_unions / ex6 - reference solution (author only).

export type Token =
  | { kind: "number"; value: number }
  | { kind: "word"; value: string }
  | { kind: "symbol"; value: string };

export function tokenise(input: string): Token[] {
  const tokens: Token[] = [];
  for (const field of input.split(/\s+/)) {
    if (field === "") {
      continue;
    }
    const asNumber = Number(field);
    if (Number.isFinite(asNumber)) {
      tokens.push({ kind: "number", value: asNumber });
    } else if (/^[A-Za-z]+$/.test(field)) {
      tokens.push({ kind: "word", value: field });
    } else {
      tokens.push({ kind: "symbol", value: field });
    }
  }
  return tokens;
}

// d07_discriminated_unions / ex7 - reference solution (author only).

export type DoorState =
  | { state: "closed" }
  | { state: "open"; since: number }
  | { state: "locked"; code: string };

export type DoorEvent =
  | { event: "open"; at: number }
  | { event: "close" }
  | { event: "lock"; code: string }
  | { event: "unlock"; code: string };

export function transition(state: DoorState, event: DoorEvent): DoorState {
  switch (state.state) {
    case "closed":
      if (event.event === "open") {
        return { state: "open", since: event.at };
      }
      if (event.event === "lock") {
        return { state: "locked", code: event.code };
      }
      return state;
    case "open":
      if (event.event === "close") {
        return { state: "closed" };
      }
      return state;
    case "locked":
      if (event.event === "unlock" && event.code === state.code) {
        return { state: "closed" };
      }
      return state;
  }
}

// d07_discriminated_unions / ex8 - reference solution (author only).

export type Expr =
  | { kind: "lit"; value: number }
  | { kind: "var"; name: string }
  | { kind: "add"; left: Expr; right: Expr }
  | { kind: "mul"; left: Expr; right: Expr }
  | { kind: "neg"; operand: Expr };

export function evaluate(expr: Expr, env: Readonly<Record<string, number>>): number {
  switch (expr.kind) {
    case "lit":
      return expr.value;
    case "var": {
      const value = env[expr.name];
      if (value === undefined) {
        throw new Error(`unknown variable: ${expr.name}`);
      }
      return value;
    }
    case "add":
      return evaluate(expr.left, env) + evaluate(expr.right, env);
    case "mul":
      return evaluate(expr.left, env) * evaluate(expr.right, env);
    case "neg":
      return -evaluate(expr.operand, env);
  }
}

export function render(expr: Expr): string {
  switch (expr.kind) {
    case "lit":
      return String(expr.value);
    case "var":
      return expr.name;
    case "add":
      return `(${render(expr.left)} + ${render(expr.right)})`;
    case "mul":
      return `(${render(expr.left)} * ${render(expr.right)})`;
    case "neg":
      return `-(${render(expr.operand)})`;
  }
}

