// d08_literals_const_enums / ex1 - reference solution (author only).

export type Direction = "north" | "east" | "south" | "west";

const CLOCKWISE: readonly Direction[] = ["north", "east", "south", "west"];

export function turnRight(direction: Direction): Direction {
  return CLOCKWISE[(CLOCKWISE.indexOf(direction) + 1) % CLOCKWISE.length];
}

// d08_literals_const_enums / ex2 - reference solution (author only).

export const SHORTCUTS = ["copy", "paste", "undo"] as const;

export type Shortcut = (typeof SHORTCUTS)[number];

export function isShortcut(value: string): value is Shortcut {
  return (SHORTCUTS as readonly string[]).includes(value);
}

export function shortcutIndex(shortcut: Shortcut): number {
  return SHORTCUTS.indexOf(shortcut);
}

// d08_literals_const_enums / ex3 - reference solution (author only).

export enum Lane {
  Left = "left",
  Center = "center",
  Right = "right",
}

const LANES: readonly Lane[] = [Lane.Left, Lane.Center, Lane.Right];

export function laneOffset(lane: Lane): number {
  return LANES.indexOf(lane) - 1;
}

export function shift(lane: Lane, by: number): Lane {
  const target = LANES.indexOf(lane) + by;
  const clamped = Math.min(LANES.length - 1, Math.max(0, target));
  return LANES[clamped];
}

// d08_literals_const_enums / ex4 - reference solution (author only).

export enum Level {
  Debug = 10,
  Info = 20,
  Warn = 30,
  Error = 40,
}

export function atLeast(level: Level, min: Level): boolean {
  return level >= min;
}

export function nameOf(level: Level): string {
  return Level[level];
}

// d08_literals_const_enums / ex5 - reference solution (author only).

export const PRICES = { standard: 500, express: 1200, overnight: 2500 } as const;

export type Speed = keyof typeof PRICES;

export function priceOf(speed: Speed): number {
  return PRICES[speed];
}

export function cheapest(): Speed {
  let best: Speed = "standard";
  for (const speed of Object.keys(PRICES) as Speed[]) {
    if (PRICES[speed] < PRICES[best]) {
      best = speed;
    }
  }
  return best;
}

// d08_literals_const_enums / ex6 - reference solution (author only).

export type Size = "s" | "m" | "l";

export type Colour = "red" | "blue";

export function sku(size: Size, colour: Colour): string {
  return `${colour}-${size}`;
}

export function parseSku(text: string): { size: Size; colour: Colour } | null {
  const parts = text.split("-");
  if (parts.length !== 2) {
    return null;
  }
  const [colour, size] = parts;
  if (colour !== "red" && colour !== "blue") {
    return null;
  }
  if (size !== "s" && size !== "m" && size !== "l") {
    return null;
  }
  return { size, colour };
}

// d08_literals_const_enums / ex7 - reference solution (author only).

export type Light = "red" | "green" | "amber";

export const NEXT: Record<Light, Light> = { red: "green", green: "amber", amber: "red" };

export function cycle(start: Light, steps: number): Light {
  const period = Object.keys(NEXT).length;
  let remaining = ((steps % period) + period) % period;
  let current = start;
  while (remaining > 0) {
    current = NEXT[current];
    remaining -= 1;
  }
  return current;
}

// d08_literals_const_enums / ex8 - reference solution (author only).

export type Weekday = "mon" | "tue" | "wed" | "thu" | "fri";

export type Weekend = "sat" | "sun";

export type Day = Weekday | Weekend;

const DAYS: readonly Day[] = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"];

export function isWeekend(day: Day): day is Weekend {
  return day === "sat" || day === "sun";
}

export function shiftDay(day: Day, by: number): Day {
  const index = DAYS.indexOf(day);
  const shifted = (((index + by) % DAYS.length) + DAYS.length) % DAYS.length;
  return DAYS[shifted];
}

export function nextWorkday(day: Day): Weekday {
  let candidate: Day = day;
  for (let i = 0; i < DAYS.length; i += 1) {
    candidate = shiftDay(candidate, 1);
    if (!isWeekend(candidate)) {
      return candidate;
    }
  }
  return "mon";
}

