// d09_generic_functions / ex1 - reference solution (author only).

export function takeWhile<T>(values: readonly T[], keep: (value: T) => boolean): T[] {
  const taken: T[] = [];
  for (const value of values) {
    if (!keep(value)) {
      return taken;
    }
    taken.push(value);
  }
  return taken;
}

// d09_generic_functions / ex2 - reference solution (author only).

export function interleave<T>(a: readonly T[], b: readonly T[]): T[] {
  const woven: T[] = [];
  const longest = Math.max(a.length, b.length);
  for (let i = 0; i < longest; i += 1) {
    if (i < a.length) {
      woven.push(a[i]);
    }
    if (i < b.length) {
      woven.push(b[i]);
    }
  }
  return woven;
}

// d09_generic_functions / ex3 - reference solution (author only).

export function zipWith<A, B, C>(
  a: readonly A[],
  b: readonly B[],
  combine: (a: A, b: B) => C,
): C[] {
  const combined: C[] = [];
  const shortest = Math.min(a.length, b.length);
  for (let i = 0; i < shortest; i += 1) {
    combined.push(combine(a[i], b[i]));
  }
  return combined;
}

// d09_generic_functions / ex4 - reference solution (author only).

export function partitionWith<T>(
  values: readonly T[],
  keep: (value: T) => boolean,
): [kept: T[], dropped: T[]] {
  const kept: T[] = [];
  const dropped: T[] = [];
  for (const value of values) {
    if (keep(value)) {
      kept.push(value);
    } else {
      dropped.push(value);
    }
  }
  return [kept, dropped];
}

// d09_generic_functions / ex5 - reference solution (author only).

export function rotate<T>(values: readonly T[], by: number): T[] {
  if (values.length === 0) {
    return [];
  }
  const offset = ((by % values.length) + values.length) % values.length;
  return [...values.slice(offset), ...values.slice(0, offset)];
}

// d09_generic_functions / ex6 - reference solution (author only).

export function memoize<A, R>(fn: (arg: A) => R, keyOf: (arg: A) => string): (arg: A) => R {
  const cache = new Map<string, R>();
  return (arg: A): R => {
    const key = keyOf(arg);
    const cached = cache.get(key);
    if (cached !== undefined || cache.has(key)) {
      return cached as R;
    }
    const value = fn(arg);
    cache.set(key, value);
    return value;
  };
}

// d09_generic_functions / ex7 - reference solution (author only).

export function mergeSorted<T>(
  a: readonly T[],
  b: readonly T[],
  compare: (x: T, y: T) => number,
): T[] {
  const merged: T[] = [];
  let i = 0;
  let j = 0;
  while (i < a.length && j < b.length) {
    if (compare(a[i], b[j]) <= 0) {
      merged.push(a[i]);
      i += 1;
    } else {
      merged.push(b[j]);
      j += 1;
    }
  }
  while (i < a.length) {
    merged.push(a[i]);
    i += 1;
  }
  while (j < b.length) {
    merged.push(b[j]);
    j += 1;
  }
  return merged;
}

// d09_generic_functions / ex8 - reference solution (author only).

export interface TreeNode<T> {
  value: T;
  children: TreeNode<T>[];
}

export function buildForest<T>(
  items: readonly T[],
  idOf: (item: T) => string,
  parentOf: (item: T) => string | null,
): TreeNode<T>[] {
  const nodes = new Map<string, TreeNode<T>>();
  for (const item of items) {
    nodes.set(idOf(item), { value: item, children: [] });
  }

  const roots: TreeNode<T>[] = [];
  for (const item of items) {
    const node = nodes.get(idOf(item));
    if (node === undefined) {
      continue;
    }
    const parentId = parentOf(item);
    const parent = parentId === null ? undefined : nodes.get(parentId);
    if (parent === undefined) {
      roots.push(node);
    } else {
      parent.children.push(node);
    }
  }
  return roots;
}

