// d10_generic_constraints / ex1 - reference solution (author only).

export function sumOf<T extends { amount: number }>(items: readonly T[]): number {
  let total = 0;
  for (const item of items) {
    total += item.amount;
  }
  return total;
}

// d10_generic_constraints / ex2 - reference solution (author only).

export function replaceById<T extends { id: string }>(items: readonly T[], updated: T): T[] {
  const index = items.findIndex((item) => item.id === updated.id);
  if (index === -1) {
    return [...items, updated];
  }
  return items.map((item, i) => (i === index ? updated : item));
}

// d10_generic_constraints / ex3 - reference solution (author only).

export function tally<K extends string>(
  keys: readonly K[],
  values: readonly string[],
): Record<K, number> {
  const counts = {} as Record<K, number>;
  for (const key of keys) {
    counts[key] = 0;
  }
  for (const value of values) {
    if (value in counts) {
      counts[value as K] += 1;
    }
  }
  return counts;
}

// d10_generic_constraints / ex4 - reference solution (author only).

export function withDefaults<T extends object, D extends object>(value: T, defaults: D): T & D {
  return { ...defaults, ...value } as T & D;
}

// d10_generic_constraints / ex5 - reference solution (author only).

export interface Cache<K, V> {
  get(key: K): V | undefined;
  set(key: K, value: V): void;
  has(key: K): boolean;
  size(): number;
}

export function makeCache<V, K extends string | number = string>(): Cache<K, V> {
  const entries = new Map<K, V>();
  return {
    get(key: K): V | undefined {
      return entries.get(key);
    },
    set(key: K, value: V): void {
      entries.set(key, value);
    },
    has(key: K): boolean {
      return entries.has(key);
    },
    size(): number {
      return entries.size;
    },
  };
}

// d10_generic_constraints / ex6 - reference solution (author only).

export function groupToMap<T, G extends string | number>(
  items: readonly T[],
  groupOf: (item: T) => G,
): Map<G, T[]> {
  const groups = new Map<G, T[]>();
  for (const item of items) {
    const key = groupOf(item);
    const bucket = groups.get(key);
    if (bucket === undefined) {
      groups.set(key, [item]);
    } else {
      bucket.push(item);
    }
  }
  return groups;
}

// d10_generic_constraints / ex7 - reference solution (author only).

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function deepMerge<A extends object, B extends object>(a: A, b: B): A & B {
  const merged: Record<string, unknown> = { ...(a as Record<string, unknown>) };
  for (const [key, value] of Object.entries(b as Record<string, unknown>)) {
    const existing = merged[key];
    if (isPlainObject(existing) && isPlainObject(value)) {
      merged[key] = deepMerge(existing, value);
    } else {
      merged[key] = value;
    }
  }
  return merged as A & B;
}

// d10_generic_constraints / ex8 - reference solution (author only).

export class VersionedStore<T extends { id: string; version: number }> {
  private readonly items = new Map<string, T>();

  put(item: T): boolean {
    const current = this.items.get(item.id);
    if (current !== undefined && current.version >= item.version) {
      return false;
    }
    this.items.set(item.id, item);
    return true;
  }

  get(id: string): T | undefined {
    return this.items.get(id);
  }

  all(): T[] {
    return [...this.items.values()].sort((a, b) =>
      a.id < b.id ? -1 : a.id > b.id ? 1 : 0,
    );
  }

  get size(): number {
    return this.items.size;
  }
}

