// d11_keyof_indexed_access / ex1 - reference solution (author only).

export function getValue<T, K extends keyof T>(source: T, key: K): T[K] {
  return source[key];
}

// d11_keyof_indexed_access / ex2 - reference solution (author only).

export function setValue<T, K extends keyof T>(source: T, key: K, value: T[K]): T {
  return { ...source, [key]: value } as T;
}

// d11_keyof_indexed_access / ex3 - reference solution (author only).

export function valuesOf<T extends object>(source: T): T[keyof T][] {
  return (Object.keys(source) as (keyof T)[]).map((key) => source[key]);
}

// d11_keyof_indexed_access / ex4 - reference solution (author only).

export function sample<T extends readonly unknown[]>(
  values: T,
  index: number,
): T[number] | undefined {
  if (!Number.isInteger(index)) {
    return undefined;
  }
  const at = index < 0 ? values.length + index : index;
  if (at < 0 || at >= values.length) {
    return undefined;
  }
  return values[at];
}

// d11_keyof_indexed_access / ex5 - reference solution (author only).

export function pluckNested<T, K extends keyof T, I extends keyof T[K]>(
  items: readonly T[],
  outer: K,
  inner: I,
): T[K][I][] {
  return items.map((item) => item[outer][inner]);
}

// d11_keyof_indexed_access / ex6 - reference solution (author only).

export const ROLES = { admin: 3, editor: 2, viewer: 1 } as const;

export type Role = keyof typeof ROLES;

export type RoleLevel = (typeof ROLES)[Role];

export function roleFor(level: RoleLevel): Role {
  for (const role of Object.keys(ROLES) as Role[]) {
    if (ROLES[role] === level) {
      return role;
    }
  }
  return "viewer";
}

export function atLeastRole(role: Role, min: Role): boolean {
  return ROLES[role] >= ROLES[min];
}

// d11_keyof_indexed_access / ex7 - reference solution (author only).

export function project<T extends object, K extends keyof T>(
  rows: readonly T[],
  keys: readonly K[],
): Pick<T, K>[] {
  return rows.map((row) => {
    const projected = {} as Pick<T, K>;
    for (const key of keys) {
      projected[key] = row[key];
    }
    return projected;
  });
}

// d11_keyof_indexed_access / ex8 - reference solution (author only).

export interface SortKey<T> {
  key: keyof T;
  direction: "asc" | "desc";
}

function compareValues(left: unknown, right: unknown): number {
  if (left === right) {
    return 0;
  }
  if (typeof left === "number" && typeof right === "number") {
    return left - right;
  }
  return String(left) < String(right) ? -1 : 1;
}

export function sortRows<T>(rows: readonly T[], by: readonly SortKey<T>[]): T[] {
  return [...rows].sort((a, b) => {
    for (const { key, direction } of by) {
      const order = compareValues(a[key], b[key]);
      if (order !== 0) {
        return direction === "asc" ? order : -order;
      }
    }
    return 0;
  });
}

