// d12_builtin_utilities / ex1 - reference solution (author only).

export interface JobDraft {
  title?: string;
  salary?: number;
  remote?: boolean;
}

export function complete(draft: JobDraft): Required<JobDraft> {
  return {
    title: draft.title ?? "untitled",
    salary: draft.salary ?? 0,
    remote: draft.remote ?? false,
  };
}

// d12_builtin_utilities / ex2 - reference solution (author only).

export type Status = "draft" | "open" | "paused" | "closed" | "archived";

export type Live = Exclude<Status, "closed" | "archived">;

export type Dead = Extract<Status, "closed" | "archived">;

export function isLive(status: Status): status is Live {
  return status !== "closed" && status !== "archived";
}

export function liveOnly(statuses: readonly Status[]): Live[] {
  return statuses.filter(isLive);
}

// d12_builtin_utilities / ex3 - reference solution (author only).

export function firstDefined<T>(
  values: readonly (T | null | undefined)[],
): NonNullable<T> | undefined {
  for (const value of values) {
    if (value !== null && value !== undefined) {
      return value as NonNullable<T>;
    }
  }
  return undefined;
}

// d12_builtin_utilities / ex4 - reference solution (author only).

export const loadPosting = (id: string, includeDrafts: boolean) => ({
  id,
  title: `posting ${id}`,
  draft: includeDrafts,
});

export type LoadArgs = Parameters<typeof loadPosting>;

export type Loaded = ReturnType<typeof loadPosting>;

export function callWith(args: LoadArgs): Loaded {
  return loadPosting(...args);
}

// d12_builtin_utilities / ex5 - reference solution (author only).

export interface Posting {
  id: string;
  title: string;
  salary: number;
  remote: boolean;
}

export function diffPatch(before: Posting, after: Posting): Partial<Posting> {
  const patch: Partial<Posting> = {};
  for (const key of Object.keys(after) as (keyof Posting)[]) {
    if (before[key] !== after[key]) {
      (patch as Record<string, unknown>)[key] = after[key];
    }
  }
  return patch;
}

// d12_builtin_utilities / ex6 - reference solution (author only).

export async function fetchPosting(id: string): Promise<{ id: string; title: string }> {
  return { id, title: `posting ${id}` };
}

export type Fetched = Awaited<ReturnType<typeof fetchPosting>>;

export async function loadAll(ids: readonly string[]): Promise<Fetched[]> {
  return Promise.all(ids.map((id) => fetchPosting(id)));
}

// d12_builtin_utilities / ex7 - reference solution (author only).

export class Search {
  constructor(
    public readonly term: string,
    public readonly limit: number,
  ) {}

  run(postings: readonly string[]): string[] {
    const needle = this.term.toLowerCase();
    return postings
      .filter((posting) => posting.toLowerCase().includes(needle))
      .slice(0, this.limit);
  }
}

export type SearchArgs = ConstructorParameters<typeof Search>;

export type SearchInstance = InstanceType<typeof Search>;

export function makeSearch(args: SearchArgs): SearchInstance {
  return new Search(...args);
}

// d12_builtin_utilities / ex8 - reference solution (author only).

export type Status = "draft" | "open" | "paused" | "closed" | "archived";

export interface Posting {
  id: string;
  title: string;
  status: Status;
  internalNotes: string;
  recruiterEmail: string;
}

export type PublicPosting = Readonly<Omit<Posting, "internalNotes" | "recruiterEmail">>;

export function publish(postings: readonly Posting[]): PublicPosting[] {
  const published: PublicPosting[] = [];
  for (const posting of postings) {
    if (posting.status === "closed" || posting.status === "archived") {
      continue;
    }
    const { internalNotes, recruiterEmail, ...rest } = posting;
    published.push(rest);
  }
  return published;
}

