// d14_mapped_types / ex4 - reference solution (author only).

export type Watchers<T> = {
  [K in keyof T & string as `${K}Changed`]: (value: T[K]) => void;
};

// d14_mapped_types / ex5 - reference solution (author only).

export type PickByType<T, V> = {
  [K in keyof T as T[K] extends V ? K : never]: T[K];
};

// d14_mapped_types / ex6 - reference solution (author only).

export type Toggles<K extends string> = {
  [P in K as `has${Capitalize<P>}`]: boolean;
};

// d14_mapped_types / ex7 - reference solution (author only).

export type Invert<T extends Record<string, PropertyKey>> = {
  [K in keyof T as T[K]]: K;
};

// d14_mapped_types / ex8 - reference solution (author only).

export type OptionalKeys<T> = {
  [K in keyof T]-?: {} extends Pick<T, K> ? K : never;
}[keyof T];

