// d15_conditional_types / ex8 - reference solution (author only).

export type Equals<X, Y> =
  (<T>() => T extends X ? 1 : 2) extends (<T>() => T extends Y ? 1 : 2)
    ? true
    : false;

// d16_infer_patterns / ex2 - reference solution (author only).

export type FirstArg<F> = F extends (first: infer A, ...rest: never[]) => unknown
  ? A
  : never;

// d16_infer_patterns / ex6 - reference solution (author only).

export type StateOf<T> = T extends {
  subscribe(listener: (state: infer S) => void): unknown;
}
  ? S
  : never;

// d16_infer_patterns / ex7 - reference solution (author only).

export type UnionToIntersection<U> = (U extends unknown ? (arg: U) => void : never) extends (
  arg: infer I,
) => void
  ? I
  : never;

// d17_template_literal_types / ex3 - reference solution (author only).

export type StartsWith<S extends string, P extends string> = S extends `${P}${string}`
  ? true
  : false;

// d17_template_literal_types / ex4 - reference solution (author only).

export type StripPrefix<S extends string, P extends string> = S extends `${P}${infer Rest}`
  ? Rest
  : S;

// d17_template_literal_types / ex5 - reference solution (author only).

export type Split<S extends string, D extends string> = S extends `${infer Head}${D}${infer Tail}`
  ? [Head, ...Split<Tail, D>]
  : [S];

// d17_template_literal_types / ex6 - reference solution (author only).

export type Join<T extends readonly string[], D extends string> = T extends readonly [
  infer Head extends string,
  ...infer Rest extends readonly string[],
]
  ? Rest extends readonly []
    ? Head
    : `${Head}${D}${Join<Rest, D>}`
  : "";

// d17_template_literal_types / ex7 - reference solution (author only).

export type SnakeToCamel<S extends string> = S extends `${infer Head}_${infer Tail}`
  ? `${Head}${Capitalize<SnakeToCamel<Tail>>}`
  : S;

// d17_template_literal_types / ex8 - reference solution (author only).

type ParamNames<S extends string> = S extends `${string}:${infer Param}/${infer Rest}`
  ? Param | ParamNames<Rest>
  : S extends `${string}:${infer Param}`
    ? Param
    : never;

export type RouteParams<S extends string> = { [K in ParamNames<S>]: string };

