// d18_guards_advanced / ex1 - reference solution (author only).

export function isNonEmpty<T>(values: T[]): values is [T, ...T[]] {
  return values.length > 0;
}

// d18_guards_advanced / ex2 - reference solution (author only).

export function hasKey<K extends PropertyKey>(
  value: object,
  key: K,
): value is Record<K, unknown> {
  return Object.prototype.hasOwnProperty.call(value, key);
}

// d18_guards_advanced / ex3 - reference solution (author only).

export function isOneOf<T extends string>(
  allowed: readonly T[],
  value: string,
): value is T {
  return (allowed as readonly string[]).includes(value);
}

// d18_guards_advanced / ex4 - reference solution (author only).

export interface Row {
  id: string;
  amount: number;
}

export function assertRow(value: unknown): asserts value is Row {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    throw new TypeError("assertRow: expected an object, received " + String(value));
  }
  const row = value as Record<string, unknown>;
  if (typeof row.id !== "string") {
    throw new TypeError("assertRow: field id must be a string");
  }
  if (typeof row.amount !== "number") {
    throw new TypeError("assertRow: field amount must be a number");
  }
}

// d18_guards_advanced / ex5 - reference solution (author only).

export type Task =
  | { kind: "email"; to: string }
  | { kind: "sms"; number: string }
  | { kind: "push"; token: string };

export function onlyKind<K extends Task["kind"]>(
  tasks: readonly Task[],
  kind: K,
): Extract<Task, { kind: K }>[] {
  return tasks.filter((task): task is Extract<Task, { kind: K }> => task.kind === kind);
}

// d18_guards_advanced / ex6 - reference solution (author only).

export function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function isStringRecord(value: unknown): value is Record<string, string> {
  return isRecord(value) && Object.values(value).every((entry) => typeof entry === "string");
}

// d18_guards_advanced / ex7 - reference solution (author only).

export function everyIs<T, S extends T>(
  guard: (value: T) => value is S,
): (values: readonly T[]) => values is readonly S[] {
  return (values: readonly T[]): values is readonly S[] =>
    values.every((value) => guard(value));
}

// d18_guards_advanced / ex8 - reference solution (author only).

export type Guard<T> = (value: unknown) => value is T;

export type GuardType<G> = G extends (value: unknown) => value is infer T ? T : never;

export function objectOf<S extends Record<string, (value: unknown) => boolean>>(
  shape: S,
): Guard<{ [K in keyof S]: GuardType<S[K]> }> {
  return (value: unknown): value is { [K in keyof S]: GuardType<S[K]> } => {
    if (typeof value !== "object" || value === null || Array.isArray(value)) {
      return false;
    }
    const record = value as Record<string, unknown>;
    return Object.entries(shape).every(
      ([key, guard]) => key in record && guard(record[key]),
    );
  };
}

