// d19_unknown_any_never / ex1 - reference solution (author only).

export function parseJson(text: string): unknown {
  return JSON.parse(text) as unknown;
}

// d19_unknown_any_never / ex2 - reference solution (author only).

export function toNumber(value: unknown): number | null {
  if (typeof value === "number") {
    return Number.isFinite(value) ? value : null;
  }
  if (typeof value === "string") {
    const trimmed = value.trim();
    if (trimmed === "") {
      return null;
    }
    const parsed = Number(trimmed);
    return Number.isFinite(parsed) ? parsed : null;
  }
  return null;
}

// d19_unknown_any_never / ex3 - reference solution (author only).

export type Shipment =
  | { status: "pending" }
  | { status: "shipped"; trackingId: string }
  | { status: "delivered"; signedBy: string }
  | { status: "cancelled"; reason: string };

export function assertUnreachable(value: never): never {
  throw new Error("assertUnreachable: unhandled value " + String(value));
}

export function describeShipment(shipment: Shipment): string {
  switch (shipment.status) {
    case "pending":
      return "waiting to ship";
    case "shipped":
      return "in transit as " + shipment.trackingId;
    case "delivered":
      return "delivered to " + shipment.signedBy;
    case "cancelled":
      return "cancelled: " + shipment.reason;
    default:
      return assertUnreachable(shipment);
  }
}

// d19_unknown_any_never / ex4 - reference solution (author only).

export interface Cache {
  set(key: string, value: unknown): void;
  get<T>(key: string, guard: (value: unknown) => value is T): T | null;
  has(key: string): boolean;
}

export function createCache(): Cache {
  const entries = new Map<string, unknown>();
  return {
    set(key: string, value: unknown): void {
      entries.set(key, value);
    },
    get<T>(key: string, guard: (value: unknown) => value is T): T | null {
      if (!entries.has(key)) {
        return null;
      }
      const value = entries.get(key);
      return guard(value) ? value : null;
    },
    has(key: string): boolean {
      return entries.has(key);
    },
  };
}

// d19_unknown_any_never / ex5 - reference solution (author only).

export type OmitNever<T> = {
  [K in keyof T as T[K] extends never ? never : K]: T[K];
};

// d19_unknown_any_never / ex6 - reference solution (author only).

export function deepGet(value: unknown, path: readonly string[]): unknown {
  let current: unknown = value;
  for (const key of path) {
    if (typeof current !== "object" || current === null) {
      return undefined;
    }
    if (!Object.prototype.hasOwnProperty.call(current, key)) {
      return undefined;
    }
    current = (current as Record<string, unknown>)[key];
  }
  return current;
}

// d19_unknown_any_never / ex7 - reference solution (author only).

export type JsonValue =
  | string
  | number
  | boolean
  | null
  | JsonValue[]
  | { [key: string]: JsonValue };

export function isJsonValue(value: unknown): value is JsonValue {
  if (value === null) {
    return true;
  }
  const kind = typeof value;
  if (kind === "string" || kind === "boolean") {
    return true;
  }
  if (kind === "number") {
    return Number.isFinite(value);
  }
  if (Array.isArray(value)) {
    return value.every((entry) => isJsonValue(entry));
  }
  if (kind === "object") {
    return Object.values(value as Record<string, unknown>).every((entry) =>
      isJsonValue(entry),
    );
  }
  return false;
}

// d19_unknown_any_never / ex8 - reference solution (author only).

export function fail(message: string): never {
  throw new Error(message);
}

export function requirePort(raw: unknown): number {
  const value: unknown = typeof raw === "string" ? Number(raw.trim()) : raw;
  if (
    typeof value !== "number" ||
    !Number.isInteger(value) ||
    value < 1 ||
    value > 65535
  ) {
    fail("requirePort: expected a port between 1 and 65535, received " + String(raw));
  }
  return value;
}

