// d20_satisfies_asconst / ex1 - reference solution (author only).

export const RETRY = {
  attempts: 3,
  backoffMs: 250,
  jitter: false,
} as const;

// d20_satisfies_asconst / ex2 - reference solution (author only).

export function minMax(values: readonly number[]) {
  return [Math.min(...values), Math.max(...values)] as const;
}

// d20_satisfies_asconst / ex3 - reference solution (author only).

export const PALETTE = {
  primary: "#0055ff",
  danger: "#ff0033",
  muted: "#8899aa",
} satisfies Record<string, `#${string}`>;

// d20_satisfies_asconst / ex4 - reference solution (author only).

export const ROUTES = [
  { path: "/", method: "GET" },
  { path: "/users", method: "GET" },
  { path: "/users", method: "POST" },
] as const satisfies readonly { path: string; method: "GET" | "POST" }[];

export type RoutePath = (typeof ROUTES)[number]["path"];

export type RouteMethod = (typeof ROUTES)[number]["method"];

// d20_satisfies_asconst / ex5 - reference solution (author only).

export interface Settings {
  mode: "strict" | "lenient";
  retries: number;
  tags: readonly string[];
}

export const CONFIG = {
  mode: "strict",
  retries: 3,
  tags: ["core"],
} satisfies Settings;

// d20_satisfies_asconst / ex6 - reference solution (author only).

export function tupleOf<const T extends readonly unknown[]>(values: T): T {
  return values;
}

// d20_satisfies_asconst / ex7 - reference solution (author only).

export const PLANS = {
  free: { seats: 1, features: ["basic"] },
  pro: { seats: 10, features: ["basic", "api"] },
  scale: { seats: 100, features: ["basic", "api", "sso"] },
} as const satisfies Record<string, { seats: number; features: readonly string[] }>;

export type PlanName = keyof typeof PLANS;

export type Feature = (typeof PLANS)[PlanName]["features"][number];

// d20_satisfies_asconst / ex8 - reference solution (author only).

export const FLAGS = {
  verbose: { kind: "boolean", default: false },
  retries: { kind: "number", default: 3 },
  out: { kind: "string", default: "dist" },
} as const satisfies Record<
  string,
  { kind: "boolean" | "number" | "string"; default: boolean | number | string }
>;

export type FlagName = keyof typeof FLAGS;

export type Flags = {
  [K in FlagName]: (typeof FLAGS)[K]["kind"] extends "boolean"
    ? boolean
    : (typeof FLAGS)[K]["kind"] extends "number"
      ? number
      : string;
};

export function defaults(): Flags {
  return {
    verbose: FLAGS.verbose.default,
    retries: FLAGS.retries.default,
    out: FLAGS.out.default,
  };
}

