// d21_async_typing / ex1 - reference solution (author only).

export async function mapSeries<T, R>(
  values: readonly T[],
  fn: (value: T, index: number) => Promise<R>,
): Promise<R[]> {
  const results: R[] = [];
  for (let index = 0; index < values.length; index += 1) {
    results.push(await fn(values[index], index));
  }
  return results;
}

// d21_async_typing / ex2 - reference solution (author only).

export interface Profile {
  user: { id: string; name: string };
  orders: readonly { id: string }[];
  unread: number;
}

export async function loadProfile(
  loadUser: () => Promise<{ id: string; name: string }>,
  loadOrders: () => Promise<readonly { id: string }[]>,
  loadUnread: () => Promise<number>,
): Promise<Profile> {
  const [user, orders, unread] = await Promise.all([loadUser(), loadOrders(), loadUnread()]);
  return { user, orders, unread };
}

// d21_async_typing / ex3 - reference solution (author only).

export async function partitionSettled<T>(
  tasks: readonly Promise<T>[],
): Promise<{ fulfilled: T[]; rejected: unknown[] }> {
  const settled = await Promise.allSettled(tasks);
  const fulfilled: T[] = [];
  const rejected: unknown[] = [];
  for (const result of settled) {
    if (result.status === "fulfilled") {
      fulfilled.push(result.value);
    } else {
      rejected.push(result.reason);
    }
  }
  return { fulfilled, rejected };
}

// d21_async_typing / ex4 - reference solution (author only).

export async function* pages<T>(
  fetchPage: (cursor: string | null) => Promise<{ items: readonly T[]; next: string | null }>,
): AsyncGenerator<T, void, undefined> {
  let cursor: string | null = null;
  for (;;) {
    const page = await fetchPage(cursor);
    for (const item of page.items) {
      yield item;
    }
    if (page.next === null) {
      return;
    }
    cursor = page.next;
  }
}

export async function collect<T>(source: AsyncIterable<T>): Promise<T[]> {
  const items: T[] = [];
  for await (const item of source) {
    items.push(item);
  }
  return items;
}

// d21_async_typing / ex5 - reference solution (author only).

export async function withRetry<T>(task: () => Promise<T>, attempts: number): Promise<T> {
  let lastError: unknown;
  for (let attempt = 0; attempt < attempts; attempt += 1) {
    try {
      return await task();
    } catch (error: unknown) {
      lastError = error;
    }
  }
  throw lastError;
}

// d21_async_typing / ex6 - reference solution (author only).

export function withTimeout<T>(
  task: Promise<T>,
  expire: Promise<void>,
  message: string,
): Promise<T> {
  const timeout: Promise<never> = expire.then(() => {
    throw new Error(message);
  });
  return Promise.race([task, timeout]);
}

// d21_async_typing / ex7 - reference solution (author only).

export interface Queue {
  add<T>(task: () => Promise<T>): Promise<T>;
}

export function createQueue(limit: number): Queue {
  let active = 0;
  const waiting: (() => void)[] = [];

  const release = (): void => {
    active -= 1;
    const next = waiting.shift();
    if (next !== undefined) {
      next();
    }
  };

  return {
    add<T>(task: () => Promise<T>): Promise<T> {
      return new Promise<T>((resolve, reject) => {
        const run = (): void => {
          active += 1;
          task().then(resolve, reject).finally(release);
        };
        if (active < limit) {
          run();
        } else {
          waiting.push(run);
        }
      });
    },
  };
}

// d21_async_typing / ex8 - reference solution (author only).

export function allOf<const T extends readonly unknown[]>(
  values: T,
): Promise<{ -readonly [K in keyof T]: Awaited<T[K]> }> {
  return Promise.all(values) as Promise<{ -readonly [K in keyof T]: Awaited<T[K]> }>;
}

