// d22_declaration_files / ex1 - reference solution (author only).

export interface Tag {
  scope: string;
  name: string;
}

export function parseTag(raw: string): Tag {
  const separator = raw.indexOf(":");
  if (separator === -1) {
    return { scope: "", name: raw };
  }
  return { scope: raw.slice(0, separator), name: raw.slice(separator + 1) };
}

export namespace parseTag {
  export const VERSION: string = "1.0";

  export function isValid(raw: string): boolean {
    return raw.includes(":");
  }
}

// d22_declaration_files / ex2 - reference solution (author only).

export function box(value: string): { kind: "text"; value: string };
export function box(value: number): { kind: "count"; value: number };
export function box(value: string | number): {
  kind: "text" | "count";
  value: string | number;
} {
  if (typeof value === "string") {
    return { kind: "text", value };
  }
  return { kind: "count", value };
}

// d22_declaration_files / ex3 - reference solution (author only).

declare global {
  // eslint-disable-next-line no-var
  var __d22BuildRegistry: Record<string, number> | undefined;
}

export function registerBuild(name: string, version: number): void {
  if (globalThis.__d22BuildRegistry === undefined) {
    globalThis.__d22BuildRegistry = {};
  }
  globalThis.__d22BuildRegistry[name] = version;
}

export function readBuild(name: string): number | undefined {
  return globalThis.__d22BuildRegistry?.[name];
}

// d22_declaration_files / ex4 - reference solution (author only).

export namespace Api {
  export interface Row {
    id: string;
    amount: number;
  }

  export type Id = Row["id"];

  export const VERSION: number = 2;
}

export function makeRow(id: Api.Id, amount: number): Api.Row {
  return { id, amount };
}

// d22_declaration_files / ex5 - reference solution (author only).

export interface RequestContext {
  requestId: string;
}

export interface RequestContext {
  locale: string;
}

export function describeContext(context: RequestContext): string {
  return context.requestId + "@" + context.locale;
}

// d22_declaration_files / ex6 - reference solution (author only).

export enum Level {
  Debug = 10,
  Info = 20,
  Error = 40,
}

export namespace Level {
  export function isAtLeast(value: Level, minimum: Level): boolean {
    return value >= minimum;
  }

  export function parse(name: string): Level | undefined {
    const found: unknown = (Level as unknown as Record<string, unknown>)[name];
    return typeof found === "number" ? (found as Level) : undefined;
  }
}

// d22_declaration_files / ex7 - reference solution (author only).

export interface CommandRegistry {}

export interface CommandRegistry {
  build: { target: string };
}

export interface CommandRegistry {
  test: { pattern: string };
}

export type CommandName = keyof CommandRegistry;

const handlers = {
  build: (payload: CommandRegistry["build"]): string => "build:" + payload.target,
  test: (payload: CommandRegistry["test"]): string => "test:" + payload.pattern,
};

export function dispatch<K extends CommandName>(name: K, payload: CommandRegistry[K]): string {
  const handler = handlers[name] as (value: CommandRegistry[K]) => string;
  return handler(payload);
}

// d22_declaration_files / ex8 - reference solution (author only).

export class Money {
  constructor(
    public readonly amount: number,
    public readonly currency: Money.Currency,
  ) {}

  plus(other: Money): Money;
  plus(amount: number): Money;
  plus(other: Money | number): Money {
    if (typeof other === "number") {
      return new Money(this.amount + other, this.currency);
    }
    if (other.currency !== this.currency) {
      throw new TypeError(
        "Money.plus: cannot add " + other.currency + " to " + this.currency + " - " +
          "one currency at a time",
      );
    }
    return new Money(this.amount + other.amount, this.currency);
  }

  toString(): string {
    return Money.SYMBOLS[this.currency] + this.amount.toFixed(2);
  }
}

export namespace Money {
  export type Currency = "USD" | "EUR";

  export const SYMBOLS: Record<Currency, string> = { USD: "$", EUR: "E" };

  export function zero(currency: Currency): Money {
    return new Money(0, currency);
  }
}

