// d23_realworld_apis / ex1 - reference solution (author only).

export type Result<T, E> = { ok: true; value: T } | { ok: false; error: E };

export function ok<T>(value: T): Result<T, never> {
  return { ok: true, value };
}

export function err<E>(error: E): Result<never, E> {
  return { ok: false, error };
}

export function unwrapOr<T, E>(result: Result<T, E>, fallback: T): T {
  return result.ok ? result.value : fallback;
}

// d23_realworld_apis / ex2 - reference solution (author only).

export interface HttpResponse {
  status: number;
  body: unknown;
}

export type Fetcher = (url: string) => Promise<HttpResponse>;

export type Fetched<T> =
  | { ok: true; data: T }
  | { ok: false; reason: "http" | "shape"; status: number };

export async function getJson<T>(
  fetcher: Fetcher,
  url: string,
  guard: (value: unknown) => value is T,
): Promise<Fetched<T>> {
  const response = await fetcher(url);
  if (response.status < 200 || response.status >= 300) {
    return { ok: false, reason: "http", status: response.status };
  }
  if (!guard(response.body)) {
    return { ok: false, reason: "shape", status: response.status };
  }
  return { ok: true, data: response.body };
}

// d23_realworld_apis / ex3 - reference solution (author only).

export function buildQuery(
  params: Record<string, string | number | boolean | undefined>,
): string {
  return Object.keys(params)
    .sort()
    .filter((key) => params[key] !== undefined)
    .map((key) => encodeURIComponent(key) + "=" + encodeURIComponent(String(params[key])))
    .join("&");
}

// d23_realworld_apis / ex4 - reference solution (author only).

export interface UserDto {
  user_id: string;
  display_name: string;
  created_at: string;
}

type SnakeToCamel<S extends string> = S extends `${infer Head}_${infer Tail}`
  ? `${Head}${Capitalize<SnakeToCamel<Tail>>}`
  : S;

export type CamelKeys<T> = {
  [K in keyof T as SnakeToCamel<K & string>]: T[K];
};

export interface User {
  userId: string;
  displayName: string;
  createdAt: Date;
}

export function toUser(dto: UserDto): User {
  return {
    userId: dto.user_id,
    displayName: dto.display_name,
    createdAt: new Date(dto.created_at),
  };
}

// d23_realworld_apis / ex5 - reference solution (author only).

export interface TtlCache<T> {
  set(key: string, value: T): void;
  get(key: string): T | undefined;
  size(): number;
}

export function createTtlCache<T>(ttlMs: number, now: () => number): TtlCache<T> {
  const entries = new Map<string, { value: T; writtenAt: number }>();

  return {
    set(key: string, value: T): void {
      entries.set(key, { value, writtenAt: now() });
    },
    get(key: string): T | undefined {
      const entry = entries.get(key);
      if (entry === undefined) {
        return undefined;
      }
      if (now() - entry.writtenAt >= ttlMs) {
        entries.delete(key);
        return undefined;
      }
      return entry.value;
    },
    size(): number {
      return entries.size;
    },
  };
}

// d23_realworld_apis / ex6 - reference solution (author only).

export type Method = "GET" | "POST";

export function describeRequest<M extends Method>(
  method: M,
  url: string,
  ...rest: M extends "GET" ? [] : [body: string]
): string {
  const [body] = rest as unknown as [string | undefined];
  return body === undefined ? method + " " + url : method + " " + url + " " + body;
}

// d23_realworld_apis / ex7 - reference solution (author only).

type ParamNames<S extends string> = S extends `${string}:${infer Param}/${infer Rest}`
  ? Param | ParamNames<Rest>
  : S extends `${string}:${infer Param}`
    ? Param
    : never;

export type PathParams<P extends string> = { [K in ParamNames<P>]: string };

export interface Route<P extends string, R> {
  path: P;
  run(url: string): R | undefined;
}

export function defineRoute<P extends string, R>(
  path: P,
  handler: (params: PathParams<P>) => R,
): Route<P, R> {
  const pattern = path.split("/");
  return {
    path,
    run(url: string): R | undefined {
      const parts = url.split("/");
      if (parts.length !== pattern.length) {
        return undefined;
      }
      const params: Record<string, string> = {};
      for (let index = 0; index < pattern.length; index += 1) {
        const segment = pattern[index];
        if (segment.startsWith(":")) {
          params[segment.slice(1)] = parts[index];
        } else if (segment !== parts[index]) {
          return undefined;
        }
      }
      return handler(params as PathParams<P>);
    },
  };
}

// d23_realworld_apis / ex8 - reference solution (author only).

export const ENDPOINTS = {
  getUser: { method: "GET", path: "/users/:id" },
  createOrder: { method: "POST", path: "/orders" },
  getPost: { method: "GET", path: "/users/:userId/posts/:postId" },
} as const satisfies Record<string, { method: "GET" | "POST"; path: string }>;

export type EndpointName = keyof typeof ENDPOINTS;

type ParamNames<S extends string> = S extends `${string}:${infer Param}/${infer Rest}`
  ? Param | ParamNames<Rest>
  : S extends `${string}:${infer Param}`
    ? Param
    : never;

export type PathParams<P extends string> = { [K in ParamNames<P>]: string };

export interface Client {
  call<K extends EndpointName>(
    name: K,
    params: PathParams<(typeof ENDPOINTS)[K]["path"]>,
  ): Promise<unknown>;
}

export function createClient(
  send: (method: string, url: string) => Promise<unknown>,
): Client {
  return {
    call<K extends EndpointName>(
      name: K,
      params: PathParams<(typeof ENDPOINTS)[K]["path"]>,
    ): Promise<unknown> {
      const endpoint = ENDPOINTS[name];
      const values = params as Record<string, string>;
      const url = endpoint.path
        .split("/")
        .map((segment) => (segment.startsWith(":") ? values[segment.slice(1)] : segment))
        .join("/");
      return send(endpoint.method, url);
    },
  };
}

