    }>();
    expectTypeOf(stringifyNumbers({ a: 1, b: "x" })).toEqualTypeOf<{ a: string; b: string }>();
    expectTypeOf<Stringified<{ nested: { a: number } }>>().toEqualTypeOf<{
      nested: { a: number };
    }>();
  });

