// d24_mixed_gauntlet / ex1 - reference solution (author only).

export function firstMatching<T, S extends T>(
  values: readonly T[],
  guard: (value: T) => value is S,
): S | undefined {
  for (const value of values) {
    if (guard(value)) {
      return value;
    }
  }
  return undefined;
}

// d24_mixed_gauntlet / ex2 - reference solution (author only).

export const RANKS = { bronze: 1, silver: 2, gold: 3 } as const satisfies Record<string, number>;

export type RankName = keyof typeof RANKS;

export type RankValue = (typeof RANKS)[RankName];

export function isHigher(a: RankName, b: RankName): boolean {
  return RANKS[a] > RANKS[b];
}

export function namesAbove(name: RankName): RankName[] {
  const names = Object.keys(RANKS) as RankName[];
  return names
    .filter((candidate) => RANKS[candidate] > RANKS[name])
    .sort((left, right) => RANKS[left] - RANKS[right]);
}

// d24_mixed_gauntlet / ex3 - reference solution (author only).

export type Stringified<T> = { [K in keyof T]: T[K] extends number ? string : T[K] };

export function stringifyNumbers<T extends Record<string, unknown>>(value: T): Stringified<T> {
  const result: Record<string, unknown> = {};
  for (const [key, entry] of Object.entries(value)) {
    result[key] = typeof entry === "number" ? String(entry) : entry;
  }
  return result as Stringified<T>;
}

// d24_mixed_gauntlet / ex4 - reference solution (author only).

export type EventOf<S extends string> = S extends `${infer Scope}:${infer Name}`
  ? { scope: Scope; name: Name }
  : never;

export function splitEvent<S extends string>(event: S): EventOf<S> {
  const separator = event.indexOf(":");
  if (separator === -1) {
    throw new TypeError("splitEvent: expected a colon in " + event);
  }
  return {
    scope: event.slice(0, separator),
    name: event.slice(separator + 1),
  } as EventOf<S>;
}

// d24_mixed_gauntlet / ex5 - reference solution (author only).

export type Command =
  | { type: "add"; item: string }
  | { type: "remove"; id: number }
  | { type: "clear" };

export function parseCommand(input: unknown): Command | null {
  if (typeof input !== "object" || input === null || Array.isArray(input)) {
    return null;
  }
  const record = input as Record<string, unknown>;
  if (record.type === "add" && typeof record.item === "string") {
    return { type: "add", item: record.item };
  }
  if (record.type === "remove" && typeof record.id === "number") {
    return { type: "remove", id: record.id };
  }
  if (record.type === "clear") {
    return { type: "clear" };
  }
  return null;
}

// d24_mixed_gauntlet / ex6 - reference solution (author only).

export async function firstSuccess<T>(tasks: readonly (() => Promise<T>)[]): Promise<T> {
  if (tasks.length === 0) {
    throw new Error("firstSuccess: no tasks were given");
  }
  let lastError: unknown;
  for (const task of tasks) {
    try {
      return await task();
    } catch (error: unknown) {
      lastError = error;
    }
  }
  throw lastError;
}

// d24_mixed_gauntlet / ex7 - reference solution (author only).

export type CartEvent =
  | { type: "added"; sku: string; qty: number }
  | { type: "removed"; sku: string }
  | { type: "quantity"; sku: string; qty: number }
  | { type: "cleared" };

export interface CartLine {
  readonly sku: string;
  readonly qty: number;
}

export interface CartState {
  readonly lines: readonly CartLine[];
}

export function assertNever(value: never): never {
  throw new Error("assertNever: unhandled value " + String(value));
}

export function reduceCart(state: CartState, event: CartEvent): CartState {
  switch (event.type) {
    case "added": {
      const existing = state.lines.find((line) => line.sku === event.sku);
      if (existing === undefined) {
        return { lines: [...state.lines, { sku: event.sku, qty: event.qty }] };
      }
      return {
        lines: state.lines.map((line) =>
          line.sku === event.sku ? { sku: line.sku, qty: line.qty + event.qty } : line,
        ),
      };
    }
    case "removed":
      return { lines: state.lines.filter((line) => line.sku !== event.sku) };
    case "quantity": {
      if (!state.lines.some((line) => line.sku === event.sku)) {
        return state;
      }
      if (event.qty <= 0) {
        return { lines: state.lines.filter((line) => line.sku !== event.sku) };
      }
      return {
        lines: state.lines.map((line) =>
          line.sku === event.sku ? { sku: line.sku, qty: event.qty } : line,
        ),
      };
    }
    case "cleared":
      return { lines: [] };
    default:
      return assertNever(event);
  }
}

// d24_mixed_gauntlet / ex8 - reference solution (author only).

export type PipeResult<T, Fns extends readonly unknown[]> = Fns extends readonly [
  (arg: never) => infer R,
  ...infer Rest,
]
  ? PipeResult<Awaited<R>, Rest>
  : T;

export function pipeAsync<T, Fns extends readonly ((arg: never) => unknown)[]>(
  input: T,
  ...fns: Fns
): Promise<PipeResult<T, Fns>> {
  const run = async (): Promise<unknown> => {
    let value: unknown = input;
    for (const fn of fns) {
      value = await (fn as (arg: unknown) => unknown)(value);
    }
    return value;
  };
  return run() as Promise<PipeResult<T, Fns>>;
}

