// i1_interview_concepts / ex1 - reference solution (author only).

export function lengthOf(value: unknown): number {
  if (typeof value === "string" || Array.isArray(value)) {
    return value.length;
  }
  if (typeof value === "object" && value !== null) {
    return Object.keys(value).length;
  }
  return 0;
}

// i1_interview_concepts / ex2 - reference solution (author only).

export type JobState =
  | { status: "queued" }
  | { status: "running"; percent: number }
  | { status: "done"; durationMs: number }
  | { status: "failed"; message: string };

function assertNever(value: never): never {
  throw new Error(`unhandled job state: ${JSON.stringify(value)}`);
}

export function describeJob(job: JobState): string {
  switch (job.status) {
    case "queued":
      return "queued";
    case "running":
      return `running (${job.percent}%)`;
    case "done":
      return `done in ${job.durationMs}ms`;
    case "failed":
      return `failed: ${job.message}`;
    default:
      return assertNever(job);
  }
}

// i1_interview_concepts / ex3 - reference solution (author only).

export interface DojoEvents {
  pass: { exercise: string };
}

// A second declaration of the same interface merges with the first.
export interface DojoEvents {
  fail: { exercise: string; message: string };
}

export function describeEvent<K extends keyof DojoEvents>(
  event: K,
  payload: DojoEvents[K],
): string {
  if (event === "fail") {
    const failure = payload as DojoEvents["fail"];
    return `fail ${failure.exercise}: ${failure.message}`;
  }
  const pass = payload as DojoEvents["pass"];
  return `pass ${pass.exercise}`;
}

// i1_interview_concepts / ex4 - reference solution (author only).

export function errorMessage(error: unknown): string {
  if (error instanceof Error) {
    return error.message;
  }
  if (typeof error === "string") {
    return error;
  }
  return "unknown error";
}

// i1_interview_concepts / review1 - reference solution (author only).

export function safeGet(source: unknown, key: string): unknown {
  if (typeof source !== "object" || source === null) {
    return undefined;
  }
  return (source as Record<string, unknown>)[key];
}

