// i2_interview_drills / challenge - reference solution (author only).

export interface Store<S> {
  getState(): S;
  setState(updater: S | ((current: S) => S)): void;
  subscribe(listener: (state: S) => void): () => void;
  select<R>(selector: (state: S) => R): R;
}

export function createStore<S>(initial: S): Store<S> {
  let state = initial;
  const listeners = new Set<(state: S) => void>();

  return {
    getState(): S {
      return state;
    },
    setState(updater: S | ((current: S) => S)): void {
      const next =
        typeof updater === "function" ? (updater as (current: S) => S)(state) : updater;
      if (Object.is(next, state)) {
        return;
      }
      state = next;
      for (const listener of [...listeners]) {
        listener(state);
      }
    },
    subscribe(listener: (state: S) => void): () => void {
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    },
    select<R>(selector: (state: S) => R): R {
      return selector(state);
    },
  };
}

// i2_interview_drills / ex1 - reference solution (author only).

export function groupBy<T>(items: readonly T[], key: (item: T) => string): Record<string, T[]> {
  const groups: Record<string, T[]> = {};
  for (const item of items) {
    const k = key(item);
    (groups[k] ??= []).push(item);
  }
  return groups;
}

// i2_interview_drills / ex2 - reference solution (author only).

export interface EventMap {
  pass: { exercise: string };
  fail: { exercise: string; message: string };
}

type Handler<K extends keyof EventMap> = (payload: EventMap[K]) => void;

export class Emitter {
  private readonly handlers = new Map<keyof EventMap, Set<(payload: never) => void>>();

  on<K extends keyof EventMap>(event: K, handler: Handler<K>): () => void {
    let set = this.handlers.get(event);
    if (set === undefined) {
      set = new Set();
      this.handlers.set(event, set);
    }
    set.add(handler as (payload: never) => void);
    return () => {
      set?.delete(handler as (payload: never) => void);
    };
  }

  emit<K extends keyof EventMap>(event: K, payload: EventMap[K]): void {
    const set = this.handlers.get(event);
    if (set === undefined) {
      return;
    }
    for (const handler of [...set]) {
      (handler as (payload: EventMap[K]) => void)(payload);
    }
  }
}

// i2_interview_drills / ex3 - reference solution (author only).

export type Callback<T> = (error: Error | null, value?: T) => void;

export type Promisified<F> = F extends (callback: Callback<infer T>) => void
  ? () => Promise<T>
  : never;

export function promisify<T>(fn: (callback: Callback<T>) => void): () => Promise<T> {
  return () =>
    new Promise<T>((resolve, reject) => {
      fn((error, value) => {
        if (error !== null) {
          reject(error);
        } else {
          resolve(value as T);
        }
      });
    });
}

// i2_interview_drills / ex4 - reference solution (author only).

export function debounce<F extends (...args: any[]) => void>(
  fn: F,
  waitMs: number,
): (...args: Parameters<F>) => void {
  let timer: ReturnType<typeof setTimeout> | undefined;
  return (...args: Parameters<F>): void => {
    if (timer !== undefined) {
      clearTimeout(timer);
    }
    timer = setTimeout(() => {
      timer = undefined;
      fn(...args);
    }, waitMs);
  };
}

// i2_interview_drills / ex5 - reference solution (author only).

export interface TreeNode {
  id: string;
  children?: TreeNode[];
}

export interface FlatNode {
  id: string;
  depth: number;
}

export function flattenTree(roots: readonly TreeNode[]): FlatNode[] {
  const flat: FlatNode[] = [];
  const walk = (nodes: readonly TreeNode[], depth: number): void => {
    for (const node of nodes) {
      flat.push({ id: node.id, depth });
      walk(node.children ?? [], depth + 1);
    }
  };
  walk(roots, 0);
  return flat;
}

// i2_interview_drills / ex6 - reference solution (author only).

export function pipe<A, B>(value: A, ab: (input: A) => B): B;
export function pipe<A, B, C>(value: A, ab: (input: A) => B, bc: (input: B) => C): C;
export function pipe<A, B, C, D>(
  value: A,
  ab: (input: A) => B,
  bc: (input: B) => C,
  cd: (input: C) => D,
): D;
export function pipe(value: unknown, ...fns: ((input: unknown) => unknown)[]): unknown {
  return fns.reduce((current, fn) => fn(current), value);
}

// i2_interview_drills / review1 - reference solution (author only).

export function mapValues<T extends object, U>(
  source: T,
  transform: (value: T[keyof T], key: keyof T & string) => U,
): Record<keyof T, U> {
  const result = {} as Record<keyof T, U>;
  for (const key of Object.keys(source) as (keyof T & string)[]) {
    result[key] = transform(source[key], key);
  }
  return result;
}

