// i3_interview_rapidfire / ex1 - reference solution (author only).

export function toNumber(value: unknown): number | null {
  if (typeof value === "number") {
    return Number.isFinite(value) ? value : null;
  }
  if (typeof value === "string" && value.trim() !== "") {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : null;
  }
  return null;
}

// i3_interview_rapidfire / ex2 - reference solution (author only).

export type Level = "beginner" | "intermediate" | "advanced" | "master";

function assertNever(value: never): never {
  throw new Error(`unhandled level: ${JSON.stringify(value)}`);
}

export function levelBadge(level: Level): string {
  switch (level) {
    case "beginner":
      return "*";
    case "intermediate":
      return "**";
    case "advanced":
      return "***";
    case "master":
      return "****";
    default:
      return assertNever(level);
  }
}

// i3_interview_rapidfire / ex3 - reference solution (author only).

export function sortByKey<T, K extends keyof T>(items: readonly T[], key: K): T[] {
  return [...items].sort((a, b) => {
    const left = a[key];
    const right = b[key];
    if (left === right) {
      return 0;
    }
    return left < right ? -1 : 1;
  });
}

// i3_interview_rapidfire / ex4 - reference solution (author only).

export type MyNonNullable<T> = T extends null | undefined ? never : T;

export type MyReturnType<F> = F extends (...args: never[]) => infer R ? R : never;

export function compact<T>(items: readonly T[]): MyNonNullable<T>[] {
  return items.filter(
    (item): item is MyNonNullable<T> => item !== null && item !== undefined,
  );
}

// i3_interview_rapidfire / review1 - reference solution (author only).

export type Method = "GET" | "POST";

export const ROUTES = {
  listLessons: { method: "GET", path: "/lessons" },
  submitAttempt: { method: "POST", path: "/attempts" },
} as const satisfies Record<string, { method: Method; path: string }>;

export function describeRoute(name: keyof typeof ROUTES): string {
  const route = ROUTES[name];
  return `${route.method} ${route.path}`;
}
